          const lx = X(282), ly = Y(209), tx = X(322);
          P.seg([[lx, ly], [tx - 4, ly]], C.new, 1.4);
          const tw = Math.max(60, L.ox + 460 * S - tx);
          const s1 = fit("основной объект", tw, 11, 700);
          txt("основной объект", tx, ly - 12, C.new, s1, 700, "left", true);
          txt("изучения", tx, ly + 1, C.new, s1, 700, "left", true);
          txt("(วัตถุศึกษาหลัก)", tx, ly + 14, C.ink2, Math.min(s1, 10.5), 500, "left");
          ctx.restore();
