        const rowH = narrowP ? 32 : 37;
        const y1 = L.py + (narrowP ? 8 : 12);
        const nDone = COMP.filter(c => k >= c.step).length;
        const unitsOn = k >= 5 ? NU : 0;
        const rowsY1 = y1 + (narrowP ? 24 : 26);
        const y2 = narrowP ? y1 : rowsY1 + NC * rowH + 14;
        const rowsY2 = y2 + (narrowP ? 24 : 26);
        const head = (label, cnt, x, y, cw, color) => {
          const s = fit(label, cw - 38, 11.5, 700);
          txt(label, x, y, C.ink, s, 700, "left");
          txt(cnt, x + cw, y, color, 15, 800, "right");
        };
