    const IPH = 10, IM = 0.02, KO = 0.5, KD = 0.2, KPH = 20, KINT = 50, KPD = 1250, MV = 2e-4;
    const A0 = IPH * IM, A1 = IPH * KO, A1P = A1 + KD * IM * KPD, A2 = KD * IM * KPH, A3 = KD * IM * KINT;
    const D2 = A1 * A2 - A0 * A3, D2P = A1P * A2 - A0 * A3;
    const S_PI = IM / KO, S_PID = A0 / A1P;                 // ความชันเส้น КГУ
    const PHST = KO * MV / (KD * IM * KINT);                 // φ_ст = k_Ω M_в / (k_Д I_М k_∫)
    const DEG = 180 / Math.PI;
    const ED = '<span class="ed">ผู้เรียบเรียงตั้งค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>', EW = '<span class="ed">ผู้เรียบเรียงเขียน</span>';
    const XM = 100, YM = 25;                                 // ขอบเขตระนาบ k_∫ × k_φ

    /* ---------- MathML ---------- */
