    const KDm = sb(mi("k"), rm("Д")), KOm = sb(mi("k"), mi("Ω")), KPm = sb(mi("k"), mi("φ")), KIm = sb(mi("k"), mo("∫")), KDDm = sb(mi("k"), dot(phi)), KIIm = sb(mi("k"), mo("∫∫"));
    const ai = (i) => sb(mi("a"), mn(i));
    const D2m = sb(mo("Δ"), mn(2));
    const Dt = '<mover accent="true"><mi>D</mi><mo>~</mo></mover>';
