    const phi = mi("φ"), om = mi("Ω");
    const IMm = sb(mi("I"), rm("М")), IPm = sb(mi("I"), mi("φ")), MDm = sb(mi("M"), rm("Д")), MUm = sb(mi("M"), rm("у")), MVm = sb(mi("M"), rm("в"));
