    const RAD = 180 / Math.PI;
    const BETA = (MV / H) * T2, BETADEG = BETA * RAD;                    // β จากไจโรเดี่ยว ที่ t = 100 с
    const HY = H * Math.cos(BETA), HZ = H * Math.sin(BETA);
    const BD2 = 1e-3;                                                      // β̇′ (สมมติ)
    const MVY = HZ * BD2;                                                  // M_вy = H_z·β̇′
    const MGZ2 = HY * BD2, PHDD2 = MGZ2 / IPH;                             // M′_Гz = H_y·β̇′ · φ̈ = M′_Гz/I_φ
    const BDP = MV / (2 * H), BP = BDP * T2;                               // ไจโรคู่ β̇ = M_в/(2H) · β ที่ 100 с
    const N2 = 3, N3 = 2;                                                  // จำนวนคู่ สองดีกรี / สามดีกรี
    const ED = '<span class="ed">ผู้เรียบเรียงตั้งค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>', EA = '<span class="ed">ผู้เรียบเรียงเสริม</span>';
    const SUP = { "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴", "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹" };
    function sci(v, d) {
      if (!isFinite(v) || v === 0) return "0";
      const a = Math.abs(v);
      let e = Math.floor(Math.log10(a) + 1e-9), ms = (a / Math.pow(10, e)).toFixed(d || 0);
      if (parseFloat(ms) >= 10) { e += 1; ms = (a / Math.pow(10, e)).toFixed(d || 0); }
      ms = ms.replace(".", ",");
      if (ms.indexOf(",") >= 0) ms = ms.replace(/0+$/, "").replace(/,$/, "");
      return (v < 0 ? "−" : "") + ms + "·10" + (e < 0 ? "⁻" : "") + String(Math.abs(e)).split("").map(c => SUP[c]).join("");
    }

    /* ---------- MathML ---------- */
    const mi = s => "<mi>" + s + "</mi>", mn = s => "<mn>" + s + "</mn>", mo = s => "<mo>" + s + "</mo>", mth = s => "<math>" + s + "</math>";
    const rm = s => '<mi mathvariant="normal">' + s + "</mi>";
    const sb = (b, s) => "<msub>" + b + "<mrow>" + s + "</mrow></msub>";
