    const ddot = b => '<mover accent="true">' + b + '<mo stretchy="false" style="font-size:1.6em">&#x00A8;</mo></mover>';
    const frac = (a, b) => "<mfrac><mrow>" + a + "</mrow><mrow>" + b + "</mrow></mfrac>";
