    const Mgz = sb(mi("M"), rm("Г") + mi("z")), Mgz2 = "<msub><msup>" + mi("M") + mo("′") + "</msup><mrow>" + rm("Г") + mi("z") + "</mrow></msub>";
    const Hy = sb(mi("H"), mi("y")), Hz = sb(mi("H"), mi("z"));
