        if (OPS.indexOf(c) >= 0) return "<mo>" + (c === "-" ? "−" : c === "<" ? "&lt;" : c === ">" ? "&gt;" : c) + "</mo>";
        let m = "<mi>" + c + "</mi>";
        if (src[i] === "̇" || src[i] === "̈") {
          const dd = src[i] === "̈"; i++;
          m = '<mover accent="true">' + m + '<mo stretchy="false" style="font-size:1.6em">' + (dd ? "&#x00A8;" : "&#x02D9;") + "</mo></mover>";
        }
