            { k: "โมเมนต์รอบแกน Yaw", v: [tm("M_y") + " = −" + tm('m ω_0^2 l^2 "sin" 2ψ'), "= −" + mN(o.My) + " мН·м"], big: true },
            { k: "เทียบกับ Pitch", v: tm("M_y : M_z") + " = " + nf(o.My / o.Mx * 4, 0) + " : " + nf(o.Mz / o.Mx * 4, 0) }
