    { const n = 200, hh = DT / n; for (let i = 0; i <= n; i++) SIM += (i === 0 || i === n ? 1 : i % 2 ? 4 : 2) * acc(i * hh); SIM *= hh / 3; }
    const HALF = DT / 2, XM = -TAU + HALF;                          // กึ่งกลางเวลาเผา (สัมพัทธ์ t_п)
    const DVL = dv(W, HALF), DVR = DVP - DVL;                       // พื้นที่ก่อน/หลังเส้นกึ่งกลางเวลา
    const DERR = TAU - HALF;                                        // เวลาคลาด
    const DV1 = dv(W2, DT);                                         // วิธีที่ 1 เมื่อแรงขับจริงสูงกว่า 3 %
    const T2 = (MN / MD) * (1 - Math.exp(-DVP / W2));               // วิธีที่ 2 (8)
    const ED = '<span class="ed">ผู้เรียบเรียงตั้งค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>', ES = '<span class="ed">ผู้เรียบเรียงสมมติ</span>';

    /* ---------- MathML ---------- */
    const mi = s => "<mi>" + s + "</mi>", mn = s => "<mn>" + s + "</mn>", mo = s => "<mo>" + s + "</mo>", mth = s => "<math>" + s + "</math>";
    const rm = s => '<mi mathvariant="normal">' + s + "</mi>";
