    const sbr = (b, s) => sub(b, rm(s));
    const sup = (b, s) => "<msup>" + b + s + "</msup>";
    const row = s => "<mrow>" + s + "</mrow>";
    const frac = (a, b) => "<mfrac>" + row(a) + row(b) + "</mfrac>";
    const dotOf = b => '<mover accent="true">' + b + '<mo stretchy="false" style="font-size:1.6em">&#x02D9;</mo></mover>';
