    const EA = '<span class="ed">ผู้เรียบเรียงประมาณ</span>', ES = '<span class="ed">ผู้เรียบเรียงเลือก</span>';

    /* ---------- MathML ---------- */
    const mi = s => "<mi>" + s + "</mi>", mn = s => "<mn>" + s + "</mn>", mo = s => "<mo>" + s + "</mo>", mth = s => "<math>" + s + "</math>";
