    const sb = (b, s) => "<msub>" + b + s + "</msub>", sp = (b, s) => "<msup>" + b + s + "</msup>";
    const dot = b => '<mover accent="true">' + b + '<mo stretchy="false" style="font-size:1.6em">&#x02D9;</mo></mover>';
    const frac = (a, b) => "<mfrac><mrow>" + a + "</mrow><mrow>" + b + "</mrow></mfrac>", sqrt = s => "<msqrt>" + s + "</msqrt>";
    const LPm = '<mo stretchy="false">(</mo>', RPm = '<mo stretchy="false">)</mo>', BAR = '<mo stretchy="false">|</mo>';
    const EQ = mo("="), MI = mo("−"), PL = mo("+");
    const OM = mi("Ω"), RH = mi("ρ");
    const Wn = sb(OM, rm("н")), Wk = sb(OM, rm("к")), W0m = sb(OM, mn(0));
    const Wsub = (c, n) => sb(OM, row(rm(c) + mn(n)));
    const R0m = sb(RH, mn(0)), R1m = sb(RH, mn(1)), Rn = sb(RH, rm("н")), Rk = sb(RH, rm("к")), Rp = sb(RH, rm("п"));
    const tO = sb(mi("t"), OM), tR = sb(mi("t"), RH), tC = sb(mi("t"), rm("ц")), tMin = sb(mi("t"), row(RH + mo(",") + rm("min")));
    const sig = sb(mi("σ"), OM), an = sb(mi("a"), mi("n")), anN = "<msubsup>" + mi("a") + mi("n") + rm("ном") + "</msubsup>";
    const absRd = BAR + dot(RH) + BAR;
    const f38 = OM + LPm + mi("t") + RPm + EQ + W0m + mo("·") + frac(mn(1), sp(row(LPm + RH + LPm + mi("t") + RPm + mo("/") + R0m + RPm), mn(2)));
    const fRk = Rk + EQ + Rn + sqrt(frac(Wn, Wk)), fTr = tR + EQ + frac(Rn + MI + Rk, absRd);
