          { k: "ตรวจแกน z ด้วยสูตรปิด", v: mth(vtr("z") + EQ + MI + W + sb(mi("z"), mn(0)) + tx(" ctg") + "<mo stretchy=\"false\">(</mo>" + W + mi("T") + "<mo stretchy=\"false\">)</mo>") + " = " + sg(ZCL, 3) + " м/с", note: "ตรงกับผล RK4" },
          { k: "ปลายทางเมื่อบินถึง T", v: "x = y = z = " + nf(Math.abs(ST[0]) + Math.abs(ST[1]) + Math.abs(ST[2]), 1) + " м" }
