        vlab([{ t: "V", sub: "(T)" }], XC(VTv[0]) + 6, YC(VTv[1]) - 2, C.meas, aVT, { align: "left" });
        vec(VTv, [0, 0], C.deep, 3.4, ap(5));
        vlab(DVL(2), (XC(VTv[0])) - 8, YC(VTv[1]) / 2 + Y0 / 2 + 2, C.deep, ap(5), { align: "right" });
        const aLeg2 = only(6);
        dashLine(VTv, [0, VTv[1]], C.deep, aLeg2); 
        dashLine(VTv, [VTv[0], 0], C.deep, aLeg2);
        vlab([{ t: "ΔV", sub: "2x" }, " = " + sg(DV2[0], 2)], XC(VTv[0] / 2), YC(VTv[1]) - 10, C.deep, aLeg2, { align: "center" });
        vlab([{ t: "ΔV", sub: "2y" }, " = " + sg(DV2[1], 2)], XC(VTv[0]) + 6, YC(VTv[1] / 2) + 14, C.deep, aLeg2, { align: "left", fit: cp.x + cp.w - XC(VTv[0]) - 8 });
        vlab(["|", { t: "ΔV", sub: "2" }, "| = " + nf(M2, 2) + " м/с"], XC(VTv[0]) + 6, YC(VTv[1] / 2) - 6, C.deep, ap(6) * mix(s => (s === 6 || s === 7 ? 1 : 0)), { align: "left", fit: cp.x + cp.w - XC(VTv[0]) - 8 });
        /* ϑ₂ (ตั้งต้นที่ปลาย V(T) วัดจากแนวขนานแกน ẋ) */
