        vlab([{ t: "ϑ", sub: "2" }, " = " + nf(TH2, 1) + "°"], XC(VTv[0]) + 18, YC(VTv[1]) + 30, C.deep, aT2, { align: "left", fit: cp.x + cp.w - XC(VTv[0]) - 22 });
        withA(only(7), () => P.ring(X0, Y0, 8, C.ok, 2.4));

