            ctx.save(); ctx.strokeStyle = col; ctx.lineWidth = 1.8; ctx.beginPath(); ctx.arc(x1, iy, 36, 0, -Math.atan2(iy - ya, base), true); ctx.stroke(); ctx.restore();
            R([{ t: "ψ", sub: String(n) }, " = " + nf(n === 1 ? PS1 : PS2, 1) + "°"], x1 + 40, iy - 12, 11, col, { weight: 700, align: "left" });
            R(["ในระนาบ x–y = " + nf(hp, 2)], (x1 + x2) / 2, iy + 12, 10, C.ink2, { align: "center", halo: 3, fit: iw });
            R([{ t: "ΔV", sub: n + "z" }, " = " + sg(D[2], 3) + " (ขยาย ×" + kk + ")"], x2 - 2, ya - 11, 10, col, { align: "right", halo: 3, fit: iw });
