          { k: "ความเร่งควบคุมของ СКД", v: mth('<mo stretchy="false">|</mo>' + arho + '<mo stretchy="false">|</mo>' + EQ + mi("a") + EQ + mn(nf(A, 1))) + " м/с²" },
          { k: "ทิศของจุดเฟส", v: [gt0 + " → ไปทางขวา", lt0 + " → ไปทางซ้าย"] }
