      const c = Math.cos(d), s = Math.sin(d);
      const rx = -B0 * c + A0 * s, ry = -B0 * s - A0 * c;    // ЦД − ЦМ หลังหมุน (หน้าจอ y ลง)
      return { rx: rx, ry: ry, a: -ry, b: -rx, alpha: ALP0 + d };
