    const dot = b => '<mover accent="true">' + b + '<mo stretchy="false" style="font-size:1.6em">&#x02D9;</mo></mover>';
    const frac = (a, b) => "<mfrac><mrow>" + a + "</mrow><mrow>" + b + "</mrow></mfrac>";
    const EQ = mo("="), MI = mo("−"), PL = mo("+");
