    const U0 = KP * PHI0 + KD * DPHI0;                         // u ที่จุดเริ่มของ ПД
    let UPDMAX = 0;
    for (let t = 0; t <= 12; t += 0.02) { const q = pd(t); UPDMAX = Math.max(UPDMAX, Math.abs(KP * q[0] + KD * q[1])); }
