    const TSW = Math.sqrt(PHI0 / AC), PSW = PHI0 - AC * TSW * TSW / 2, DSW = -AC * TSW, TK = 2 * TSW;
    const leg1 = t => [PHI0 - AC * t * t / 2, -AC * t];
    const leg2 = tau => [PSW + DSW * tau + AC * tau * tau / 2, DSW + AC * tau];
    const swOurs = p => Math.sqrt(2 * AC * Math.abs(p)), swDoc = p => 2 * Math.sqrt(Math.abs(p));
