    const ED = '<span class="ed">ผู้เรียบเรียงตั้งค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>';

    /* ---------- MathML ---------- */
    const mi = s => "<mi>" + s + "</mi>", mn = s => "<mn>" + s + "</mn>", mo = s => "<mo>" + s + "</mo>", mth = s => "<math>" + s + "</math>";
