          P.arrow(lx, by(1), cx - bw / 2 - 2, by(1), C.meas, 2.4, 8);
          R(["ทำซ้ำ"], lx - 4, (by(1) + by(3)) / 2, 11.5, C.meas, { align: "right", weight: 700 });
