          R(["ผลลัพธ์"], cx + bw / 2 + 30, by(1) - 8, 12, C.ok, { align: "left", weight: 700 });
          R(["เมื่อ «ยอมรับได้»"], cx + bw / 2 + 30, by(1) + 8, 10.5, C.ok, { align: "left", weight: 700, fit: Dg.x + Dg.w - (cx + bw / 2 + 34) });
          ctx.restore();
