            ctx.fillStyle = rw[2]; ctx.globalAlpha *= 0.85; ctx.fillRect(sx0, yc - Math.min(8, sdy * 0.3), Math.max(1, (SX(rw[1]) - sx0) * g), Math.min(16, sdy * 0.6)); ctx.globalAlpha /= 0.85;
