    const rM = mth(absm(mi("R")) + mo("/") + mi("m")), pM = mth(absm(mi("P")) + mo("/") + mi("m")), fM = mth(absm(mi("F")) + mo("/") + mi("m"));
    const qM = mth(mi("q") + EQ + frac(mi("ρ") + pw(sb(mi("V"), "в"), 2), mn(2)));
    const xM = mth(mi("X") + EQ + MI + sb(mi("c"), "x") + mi("q") + mi("S"));
