          const Zp = mv(RY, Z0);
          axis(Zp, 0.9, C.lin, 1.8, [{ t: "Z", sup: "′" }], { dash: true, off: 12 });
          const m1 = arc(a => mv(Ry(a), [0.85, 0, 0]), 0, PSI, 1, C.meas, 3);
          const m2 = arc(a => mv(mm(RY, Rz(a)), [0.78, 0, 0]), 0, THE, 1, C.lin, 3);
          const m3 = arc(a => mv(mm(RYZ, Rx(a)), [0, 0.66, 0]), 0, GAM, 1, C.deep, 3);
          if (m1) R(["ψ"], m1[0] + 2, m1[1] + 13, 14, C.meas, { align: "center", weight: 700 });
          if (m2) R(["ϑ"], m2[0] - 6, m2[1] - 12, 14, C.lin, { align: "center", weight: 700 });
