          [X0, Y0, Z0].forEach((a, i) => {            // มุม α_i ระหว่างแกน ς_θ กับแกนอ้างอิง
            const f = t => { const s1 = Math.sin((1 - t) * ALP), s2 = Math.sin(t * ALP), d = Math.sin(ALP); return a.map((x, j) => (s1 * x + s2 * NV[j]) / d * 0.42); };
            const pts = []; for (let q = 0; q <= 12; q++) pts.push(pr(f(q / 12)));
            P.seg(pts, C.ink2, 1.4, [3, 3]);
            if (k >= 3 || i === 0) { const mp = pr(f(0.5).map(x => x * 1.45)); R([{ t: "α", sub: String(i + 1) }], mp[0], mp[1], 11, C.ink2, { align: "center", weight: 700 }); }
          });
          axis(NV, 1.28, C.new, 4.2, [{ t: "ς", sub: "θ" }], { head: 12, size: 14, off: 14 });
          const rho = 0.64, end = rod(NV, TH);
