        R(["φ, °"], L.r - 4, Y(0) - 11, 11.5, C.ink2, { align: "right", weight: 700 });
        R([PHd, ", °/с"], X(0) + 7, L.y + 11, 11.5, C.ink2, { weight: 700 });
