    const uDUS = DPHI >= DPHI1 ? 1 : DPHI <= -DPHI1 ? -1 : 0;
    /* บริเวณบนระนาบเฟสตามรูป 9 และกฎตรรกะตามสไลด์ 18 */
    const GRID = [[7, 8, 1], [6, 9, 2], [5, 4, 3]];
    const col = PHI >= PHI1 ? 2 : PHI <= -PHI1 ? 0 : 1, row = DPHI >= DPHI1 ? 0 : DPHI <= -DPHI1 ? 2 : 1;
    const REG = GRID[row][col];
