    const phiOnV = (s, wv, v) => vert(s, wv) + s * v * v / (2 * wv);   // φ ที่ความเร็ว v บนวิถี
    const T0 = (0 - PHI0) / DPHI0;                                // เวลาถึง φ = 0 เมื่อ Φ = 0
    const VP = vert(1, W1), VM = vert(-1, W1), VM2 = vert(-1, W2);
