        const L = { x: narrow ? 36 : 48, y: 12, r: w - 12, b: h - (narrow ? 30 : 34) };
        const X = v => L.x + (v - XMIN) / (XMAX - XMIN) * (L.r - L.x);
        const Y = v => L.b - (v + YMAX) / (2 * YMAX) * (L.b - L.y);
