    const phi = mi("φ"), dphi = dot(phi), wn = sb(mi("w"), rm("ном")), wv = sb(mi("w"), rm("в"));
    const phi1 = sb(phi, mn(1)), dphi1 = sb(dphi, mn(1)), phia1 = sb(phi, "<mrow><mi>а</mi><mn>1</mn></mrow>"), phia2 = sb(phi, "<mrow><mi>а</mi><mn>2</mn></mrow>");
