        lab([nf(T34, 2) + " с · УРД ติดเฉลี่ย " + nf(DUTY * 100, 0) + " %"], X(4.3), Y(-0.5) + 33, C.deep, g3, { align: "center" }, 11);
        /* ภาพขยายโหมดเลื่อน (ขั้น 4) */
