    const UP1 = KP * PHI1;                                    // u_φ1 = k_φ·φ₁
    const XMIN = -6.5, XMAX = 6.5, YMIN = -3, YMAX = 3;
    const ED = '<span class="ed">ผู้เรียบเรียงตั้งค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>', EF = '<span class="ed">ผู้เรียบเรียงเติม</span>';

