    const Phi = u => (u > 0 ? -1 : u < 0 ? 1 : 0) * gam(Math.abs(u));
    const bnd = (u, f) => (u - uphi(f)) / KD;                  // φ̇ ของเส้น u_у = u
    const LV = [U2, U1, -U1, -U2];
