    const u1 = sb(mi("u"), mn(1)), u2 = sb(mi("u"), mn(2)), phi1 = sb(phi, mn(1)), uph1 = sb(mi("u"), phi + mn(1)), gmin = sb(mi("γ"), rm("min"));
