        P.arrow(X(0), L.b, X(0), L.y + 1, C.ink3, 1.4, 8);
        [yP, yM].forEach(fn => P.seg([toPx([XMIN, fn(XMIN)]), toPx([XMAX, fn(XMAX)])], C.meas, 2.4, [9, 6]));

