        TY.v.forEach(v => R([nf(v, TY.d)], L.x - 5, Y(v), 10.5, C.ink3, { align: "right", halo: 0 }));
        R(["φ, °"], L.r - 4, Y(0) + 11, 11.5, C.ink2, { align: "right", weight: 700 });
        R([PHd, ", °/с"], X(0) + 6, L.y + 11, 11.5, C.ink2, { weight: 700 });

        /* ป้ายบนภาพ */
        const lab = (parts, x, y, color, a, o) => { if (a > 0.02) { ctx.save(); ctx.globalAlpha = a; R(parts, x, y, 11.5, color, Object.assign({ weight: 700 }, o || {})); ctx.restore(); } };
        const pinX = x => Math.max(L.x + 8, Math.min(L.r - 8, x)), pinY = y => Math.max(L.y + 12, Math.min(L.b - 12, y));
        lab(["Φ = −1"], pinX(X(5.8)), pinY(Y(1.42)), C.ink2, 1, { align: "right" });
        lab(["Φ = +1"], pinX(X(XMIN) + 6), pinY(Y(-1.35)), C.ink2, 1, { align: "left" });
        lab(["Φ = 0"], pinX(X(XMIN) + 6), pinY(Y(0.95)), C.ink2, 1, { align: "left" });
        lab([{ t: "L", sub: "+", s: 1.3 }], X(-0.45) + 4, Y(yP(-0.45)) - 13, C.meas, 1, { align: "left" });
        lab([{ t: "L", sub: "−", s: 1.3 }], X(-0.45) + 4, Y(yM(-0.45)) + 13, C.meas, 1, { align: "left" });
        const tsec = v => " · " + nf(v, v % 1 ? 1 : 0) + " с";
        const pl = (pp, parts, dx, dy, al, a) => lab(parts, X(pp[0]) + dx, Y(pp[1]) + dy, C.new, a * (inV(pp) ? 1 : 0), { align: al });
        pl(S0, ["S ", pt(S0, 1)], -9, -12, "right", PTS[0][1]);
