    const AU = [0, 0.8, 2, Math.SQRT2 * U2, 4, 4];                         // a_u ของแต่ละขั้น (ขั้นที่ 1 ยังไม่ป้อนสัญญาณ ใช้ภาพของขั้นที่ 2)
    const q2f = a => (a <= U2 ? 0 : 4 * W1 / (PI * a) * Math.sqrt(1 - U2 * U2 / (a * a)));   // สูตร (1)
    const Fn = u => (u > U2 ? W1 : u < -U2 ? -W1 : 0);                      // ขั้นบันไดของ УРД (ละเครื่องหมายลบของรูป 4)
    const NUM = 100000;
