    const Q2f = AU.map((a, i) => (i >= 1 ? q2f(a) : 0));                  // q₂ จากสูตร (1)
    const Q2MAX = 2 * W1 / (PI * U2);
    const ED = '<span class="ed">ผู้เรียบเรียงเลือกค่า</span>', EC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>';

    /* ---------- MathML ---------- */
